@microsoft-github-policy-service agree [company="{your company}"] @microsoft-github-policy-service agree I wanted to unit test the changes in this PR, but I was not able to get it working due to the `Application.Current.Dispatcher.Invoke` call. The test runner hangs when the second unit test runs.

My idea was to test like this:

```cs
[STATestMethod]
public void ExecuteResultActionThatReturnsTrueShouldHideTheMainView()
{
    // Arrange
    PluginManager.SetAllPlugins(new List<PluginPair>());

    if (Application.Current == null)
    {
        var temp = new Application();
    }

    var result = new Result();
    result.Action = _ => true;
    result.OriginQuery = new Query(string.Empty);

    var mainViewModel = new MainViewModel(new PowerToysRunSettings(), CancellationToken.None);
    mainViewModel.Results.SelectedItem = new ResultViewModel(result);

    // Assert
    Assert.AreEqual(Visibility.Visible, mainViewModel.MainWindowVisibility);

    // Act
    mainViewModel.OpenResultWithKeyboardCommand.Execute(0);

    // Assert
    Assert.AreEqual(Visibility.Collapsed, mainViewModel.MainWindowVisibility);
}

[STATestMethod]
public void ExecuteResultActionThatReturnsFalseShouldNotHideTheMainView()
{
    // Arrange
    PluginManager.SetAllPlugins(new List<PluginPair>());

    if (Application.Current == null)
    {
        var temp = new Application();
    }

    var result = new Result();
    result.Action = _ => false;
    result.OriginQuery = new Query(string.Empty);

    var mainViewModel = new MainViewModel(new PowerToysRunSettings(), CancellationToken.None);
    mainViewModel.Results.SelectedItem = new ResultViewModel(result);

    // Assert
    Assert.AreEqual(Visibility.Visible, mainViewModel.MainWindowVisibility);

    // Act
    mainViewModel.OpenResultWithKeyboardCommand.Execute(0);

    // Assert
    Assert.AreEqual(Visibility.Visible, mainViewModel.MainWindowVisibility);
}
```

